import {SCENES} from '../../src/nocturne.mjs';
export function scenario(wants,self=0){return SCENES.map(q=>{if(q.self)return 1<<self;if(q.boundary)return 3;if(q.context)return 1;const options=q.choices.map((c,i)=>({i,s:c.signals.filter(s=>wants.includes(s)).length})).filter(c=>c.s&&!q.choices[c.i].signals.some(s=>['lead','yield','sadism','masochism','giveCare','receiveCare','switch'].includes(s)&&!wants.includes(s))).sort((a,b)=>b.s-a.s);if(options.length)return options.slice(0,2).reduce((m,c)=>m|(1<<c.i),0);const neutral=q.choices.findIndex(c=>c.signals.some(s=>['neutral','quiet','equal','space'].includes(s)));return neutral>=0?1<<neutral:null;});}
